//! 🧪️ Actual original post and authored registrations preserve all denied and cancelled alias births.
use super::*;
use semio_framework_value::retained_clone::RetainedCloneSource;
fn grant()->RetainedCloneGrant{RetainedCloneGrant{maximum_items:64,maximum_copy_bytes:16*1024*1024,maximum_capacity_bytes:16*1024*1024,maximum_release_bytes:16*1024*1024,maximum_depth:128}}
#[test]fn genuine_final_source_pair_is_original_bound_and_paid_closed(){let laws:serde_json::Value=serde_json::from_str(include_str!("🧪️.json")).unwrap();for cut in laws["cancelCuts"].as_array().unwrap(){let(mut live,_)=RetainedCloneSource::admit_owned(crate::snapshot::empty_layout_snapshot(),(),grant()).unwrap_or_else(|_|panic!("actual live-post source"));let(mut authored,_)=RetainedCloneSource::admit_owned(7usize,(),grant()).unwrap_or_else(|_|panic!("actual authored source"));let(mut other_live,_)=RetainedCloneSource::admit_owned(crate::snapshot::empty_layout_snapshot(),(),grant()).unwrap_or_else(|_|panic!("other live source"));let(mut other_authored,_)=RetainedCloneSource::admit_owned(7usize,(),grant()).unwrap_or_else(|_|panic!("other authored source"));let mut actor=FinalGraphSourceBindings::new();let mut capacity=0;for _ in 0..cut.as_u64().unwrap(){for denied in [Default::default(),RetainedCloneGrant{maximum_copy_bytes:0,..grant()},RetainedCloneGrant{maximum_capacity_bytes:0,..grant()},RetainedCloneGrant{maximum_depth:0,..grant()}]{let d=actor.demand(live.borrow(),authored.borrow(),denied.maximum_copy_bytes).unwrap();if !retained_clone_grant_admits(denied,d){assert_eq!(actor.advance(live.borrow(),authored.borrow(),denied.maximum_copy_bytes,denied).unwrap().progress(),Default::default())}}let p=actor.advance(live.borrow(),authored.borrow(),grant().maximum_copy_bytes,grant()).unwrap().progress();assert!(p.fits(grant()));capacity+=p.retained_capacity_bytes;}if cut.as_u64().unwrap()>0{assert!(actor.verify(other_live.borrow(),authored.borrow()).is_err());assert!(actor.verify(live.borrow().project(9,|v|v),authored.borrow()).is_err());}if cut.as_u64().unwrap()==2{assert!(actor.verify(live.borrow(),other_authored.borrow()).is_err());assert!(actor.verify(live.borrow(),authored.borrow().project(9,|v|v)).is_err());}actor.begin_close();let mut released=0;while !actor.terminal_is_empty(){let denied=RetainedCloneGrant{maximum_items:0,..grant()};assert_eq!(actor.close_step(denied).unwrap().progress(),Default::default());let p=actor.close_step(grant()).unwrap().progress();assert!(p.fits(grant()));released+=p.released_bytes;}assert_eq!(released,capacity);while !live.terminal_is_empty(){live.close_step(grant()).unwrap();}while !authored.terminal_is_empty(){authored.close_step(grant()).unwrap();}while !other_live.terminal_is_empty(){other_live.close_step(grant()).unwrap();}while !other_authored.terminal_is_empty(){other_authored.close_step(grant()).unwrap();}}}
